// Turns notes/notes-src.json into js/notes.js.
//
// The source refers to lines by their number on the app's translation sheet
// (Settings → Copy all lyrics). This script swaps each number for a fingerprint
// of that line, so the generated file contains no lyrics. It needs a lyrics
// pack exported from the app (Settings → Export) to know which line is which:
//
//   node tools/build-notes.mjs path/to/pack.json

import fs from 'node:fs';
import { lineKey } from '../js/linekey.js';

const packPath = process.argv[2];
if (!packPath) throw new Error('usage: node tools/build-notes.mjs <pack.json exported from the app>');
const pack = JSON.parse(fs.readFileSync(packPath, 'utf8'));
const src = JSON.parse(fs.readFileSync(new URL('../notes/notes-src.json', import.meta.url), 'utf8'));

const out = {};
for (const [id, song] of Object.entries(src)) {
  const entry = pack.songs[id];
  if (!entry) throw new Error(`pack has no lyrics for "${id}"`);
  const distinct = [...new Set(entry.lines.map((l) => l.ru))]; // same order as the sheet
  const key = (n) => {
    const ru = distinct[+n - 1];
    if (ru == null) throw new Error(`${id}: there is no line ${n} (the song has ${distinct.length})`);
    return lineKey(ru);
  };
  const g = {};
  const f = {};
  for (const [n, text] of Object.entries(song.gist || {})) g[key(n)] = text;
  for (const [n, [en, note]] of Object.entries(song.fix || {})) f[key(n)] = note ? [en, note] : [en];
  for (const [n, note] of Object.entries(song.note || {})) f[key(n)] = [null, note];
  if (Object.keys(g).length !== Object.keys(song.gist || {}).length) throw new Error(`${id}: two captions landed on the same line`);
  out[id] = { g, f };
}

const body = `// GENERATED by tools/build-notes.mjs from notes/notes-src.json — edit that file instead.
//
// Meaning notes for each song, attached to lines by fingerprint (see linekey.js):
//   g: caption shown above the line that opens a verse or chorus
//   f: [corrected translation or null, explanation] for lines that machine
//      translation gets wrong — idioms, proverbs, cultural references

export const NOTES = ${JSON.stringify(out, null, 1)};
`;
fs.writeFileSync(new URL('../js/notes.js', import.meta.url), body);
console.log(`wrote js/notes.js: ${Object.keys(out).length} songs`);
